fn chunk_ranges(total: usize, chunks: usize) -> Vec<(usize, usize)> {
    if chunks == 0 {
        return vec![];
    }

    let mut ranges = Vec::with_capacity(chunks);
    let chunk_size = total / chunks;
    let mut remainder = total % chunks;

    for i in 0..chunks {
        let start = i * chunk_size + if i < remainder { 1 } else { 0 };
        let end = if i < remainder {
            start + chunk_size + 1
        } else {
            start + chunk_size
        };
        ranges.push((start, end));
    }

    ranges
}
